//! BetterDesk Desktop native core.
//!
//! The crate owns configuration validation, interoperability framing and
//! transport/session primitives. The Flutter application talks to this core
//! through the small exported ABI in addition to the higher-level bridge
//! generated by the desktop build.

#[allow(clippy::all)]
pub mod hbb {
    include!(concat!(env!("OUT_DIR"), "/hbb.rs"));
}

